package com.transportlogistics.app.freight.manifest.adapters.inbound.web;
import com.transportlogistics.app.freight.manifest.adapters.inbound.web.controllers.CargoManifestController;import com.transportlogistics.app.freight.manifest.adapters.inbound.web.mappers.CargoManifestWebMapper;import com.transportlogistics.app.freight.manifest.domain.model.CargoManifest;import com.transportlogistics.app.freight.manifest.ports.inbound.CargoManifestUseCase;import com.transportlogistics.app.shared.domain.ConflictException;import com.transportlogistics.app.shared.web.GlobalExceptionHandler;import org.junit.jupiter.api.*;import org.springframework.http.MediaType;import org.springframework.test.web.servlet.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import java.time.OffsetDateTime;import java.util.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class CargoManifestControllerTest {CargoManifestUseCase manifests;MockMvc mvc;UUID id=UUID.randomUUID();@BeforeEach void setup(){manifests=mock(CargoManifestUseCase.class);mvc=MockMvcBuilders.standaloneSetup(new CargoManifestController(manifests,new CargoManifestWebMapper())).setControllerAdvice(new GlobalExceptionHandler()).build();}
 @Test void createsFromSavedOrder()throws Exception{when(manifests.create(any(),eq("manager"))).thenReturn(manifest());mvc.perform(post("/v1/freight/manifests").principal(()->"manager").contentType(MediaType.APPLICATION_JSON).content("{\"freightOrderId\":\""+UUID.randomUUID()+"\"}")).andExpect(status().isCreated()).andExpect(jsonPath("$.manifestNumber").value("CM-2026-000001")).andExpect(jsonPath("$.finalized").value(false));}
 @Test void validatesBeforeMutation()throws Exception{mvc.perform(post("/v1/freight/manifests/{id}/items",id).principal(()->"manager").contentType(MediaType.APPLICATION_JSON).content("{\"version\":0,\"quantity\":0}")).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("VALIDATION_ERROR"));verifyNoInteractions(manifests);}
 @Test void mapsStaleVersionTo409()throws Exception{when(manifests.finalizeManifest(eq(id),eq(0L),eq("manager"))).thenThrow(new ConflictException("CARGO_MANIFEST_CONCURRENT_UPDATE","Reload"));mvc.perform(post("/v1/freight/manifests/{id}/finalize",id).principal(()->"manager").contentType(MediaType.APPLICATION_JSON).content("{\"version\":0}")).andExpect(status().isConflict()).andExpect(jsonPath("$.code").value("CARGO_MANIFEST_CONCURRENT_UPDATE"));}
 @Test void exposesStructuredReadiness()throws Exception{when(manifests.validate(id)).thenReturn(new CargoManifestUseCase.Readiness(false,List.of(new com.transportlogistics.app.freight.manifest.domain.model.ManifestValidationFailure("UNMANIFESTED_CARGO","items","Cargo missing"))));mvc.perform(get("/v1/freight/manifests/{id}/readiness",id)).andExpect(status().isOk()).andExpect(jsonPath("$.ready").value(false)).andExpect(jsonPath("$.failures[0].code").value("UNMANIFESTED_CARGO"));}
 private CargoManifest manifest(){var now=OffsetDateTime.parse("2026-08-25T00:00:00Z");return new CargoManifest(id,"CM-2026-000001",UUID.randomUUID(),"FO-2026-000001",List.of(),0,now,now,"manager","manager",null,null);}}
